function poly(coef, x){ var v=0; for(var i=0;i<coef.length;i++){ v=v*x+coef[i]; } return v; }
function polyDeriv(coef){ var d=[]; for(var i=0;i<coef.length-1;i++){ d.push(coef[i]*(coef.length-1-i)); } return d; }
function newton(coef, x0, tol){ var d=polyDeriv(coef);
  for(var i=0;i<200;i++){ var f=poly(coef,x0), g=poly(d,x0); if(g===0) break;
    var x1=x0 - f/g; if(Math.abs(x1-x0)<tol) return x1; x0=x1; }
  return x0; }
var EXPORTS={poly:poly,polyDeriv:polyDeriv,newton:newton};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.NewtonForgePure = EXPORTS; }
